pub fn eql(self: SemverString, that: SemverString, this_buf: []const u8, that_buf: []const u8) bool {
            if ((self.isInline() and that.isInline())) {
                return (@as(u64, @bitCast(self.bytes)) == @as(u64, @bitCast(that.bytes)));
            } else {
                if ((self.isInline() != that.isInline())) {
                    return false;
                } else {
                    const a = self.ptr();
                    const b = that.ptr();
                    const a_off: usize = a.off;
                    const a_len: usize = a.len;
                    const b_off: usize = b.off;
                    const b_len: usize = b.len;
                    if ((((a_off + a_len) > this_buf.len) or ((b_off + b_len) > that_buf.len))) {
                        return false;
                    }
                    return strings.eql(this_buf[a_off..][0..a_len], that_buf[b_off..][0..b_len]);
                }
            }
    }

