pub fn len(self: SemverString) usize {
            switch ((self.bytes[7] & 128)) {
0 => {
if ((self.bytes[0] == 0)) {
                return 0;
            }
            var i: usize = 0;
            _ = &i;
            while ((i < 8)) : (i = (i + 1)) {
                if ((self.bytes[@as(usize, @intCast(i))] == 0)) {
                    return i;
                }
            }
            return 8;
},
else => {
const ptr_ = self.ptr();
            return ptr_.len;
},
}
    }

pub inline fn ptr(self: SemverString) Pointer {
            return @as(Pointer, @bitCast((@as(u64, @bitCast(self)) & 9223372036854775807)));
